SELECT i.id AS id, i.code AS code, i.name AS name, COALESCE(i.intro, '') AS intro, i.kind AS kind, i.visibility AS visibility, i.status AS status, i.owner AS owner, 'single' AS my_role, (SELECT COUNT(*) FROM subject_student s WHERE s.subject_id = i.id AND s.status = 'active') AS student_n, (CASE WHEN i.owner <> '' THEN 1 ELSE 0 END) + (SELECT COUNT(*) FROM subject_teacher t2 WHERE t2.subject_id = i.id AND t2.teacher <> i.owner) AS teacher_n FROM subject_info i ORDER BY i.id
